INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100136, 'spa', 'bondad, benevolencia', 'bondad, benevolencia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100138, 'spa', 'bienes, abundancia material', 'bienes, abundancia material');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100144, 'spa', 'prosperidad, bienestar', 'prosperidad, bienestar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100147, 'spa', 'hermosura, belleza', 'hermosura, belleza');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100165, 'spa', 'Tobías/Tobiyyahu (nombre propio)', 'Tobías/Tobiyyahu (nombre propio): nombre propio teofórico que significa ''Yah(u) es mi bien'', que identifica a varias figuras del Antiguo Testamento. El más prominente es el oficial amonita Tobías, quien se opuso tenazmente a la reconstrucción de los muros de Jerusalén por parte de Nehemías mediante burlas, conspiraciones e intrigas políticas (Neh 2:10, 19; 3:35; 4:1; 6:1, 12, 14, 17, 19; 13:4, 7-8). Su influencia llegó tan lejos que se había asegurado una cámara dentro del recinto del templo, de la cual Nehemías expulsó físicamente sus pertenencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100172, 'spa', 'Revocar, enlucir', 'Revocar, enlucir o recubrir físicamente una pared o superficie con arcilla, cal u otro material similar. Es central en el rito de purificación de una casa afectada por moho en Levítico 14:42-48, donde el revocado sigue a la remoción de las piedras contaminadas. También se emplea para el revestimiento con oro (1 Cr 29:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100182, 'spa', 'Frontales devocionales', 'Frontales o bandas en la frente que simbolizan devoción a la Torá. Éxodo 13:16 ordena que la consagración del primogénito «será como frontales entre tus ojos», una señal memorial. Deuteronomio 6:8 instruye atar los mandamientos «como frontales entre tus ojos». Deuteronomio 11:18 repite esto, haciendo las palabras de Dios «frontales entre vuestros ojos». Ya sea entendida literal o figuradamente, la imagen enfatiza la presencia constante de la Torá en la mente del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100183, 'spa', 'Arrojar, lanzar', 'Sentido activo de arrojar, lanzar o tirar algo o alguien con fuerza. Saúl arroja su lanza contra David (1 S 18:11, 20:33), Dios arroja a Israel al exilio (Jer 16:13, 22:26) y Ezequiel describe un cuerpo arrojado al campo abierto (Ez 32:4). La forma Pilpel en Isaías 22:17 intensifica la violencia, transmitiendo la idea de un lanzamiento brutal e irresistible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100186, 'spa', 'Ser arrojado, ser echado', 'Sentido pasivo de ser lanzado o echado, expresado en la conjugación Hofal. La suerte es echada en el regazo (Pr 16:33) y los aliados traidores de Jeremías son descritos como arrojados lejos (Jer 22:28). El sentido permanece físico y literal: el sujeto recibe la fuerza de ser lanzado en lugar de iniciarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100189, 'spa', 'Ser derribado, ser derrocado', 'Extensión figurada del pasivo: ser derribado, derrocado o humillado, con énfasis en la derrota más que en el mero desplazamiento físico. Job 41:9 pregunta si el oponente de Leviatán es abatido con solo verlo, y el Salmo 37:24 asegura que el justo podrá caer pero no será totalmente abandonado. El paso del lanzamiento literal al derrocamiento metafórico es notable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100195, 'spa', 'Hilera, hilada, fila — disposición horizontal ordenada de objetos colocados uno ', 'Hilera, hilada, fila — disposición horizontal ordenada de objetos colocados uno junto a otro. En el pectoral sacerdotal, cuatro hileras contienen doce piedras preciosas que representan las tribus de Israel (Éx 28:17-20; 39:10-13). En la arquitectura salomónica, el término designa hiladas de piedra labrada (1 Re 6:36; 7:12), filas de columnas de cedro (1 Re 7:2-3) y hileras de granadas decorativas en los capiteles de las columnas (1 Re 7:18, 42). Ezequiel lo usa para las repisas de cocina alrededor de un atrio del templo (Ez 46:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100207, 'spa', 'Moler', 'Moler grano o material duro con piedra de molino, reduciéndolo a harina o polvo. El verbo טָחַן abarca la molienda del maná (Núm 11:8), el becerro de oro pulverizado (Éx 32:20; Dt 9:21), la humillación de Sansón en prisión (Jue 16:21) y la princesa babilónica obligada a moler (Is 47:2). Metafóricamente designa la opresión de los pobres (Is 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100216, 'spa', 'Tumores, hemorroides', 'Tumores o hemorroides — hinchazón patológica enviada como plaga divina. Aparece como lectura del Qeré sustituyendo el Ketiv ofalim en la narrativa del arca (1 Sam 5:6, 9, 12; 6:4-5, 11, 17) y en Deuteronomio 28:27 entre las maldiciones del pacto. Los filisteos fabricaron imágenes doradas de tumores como ofrendas votivas (1 Sam 6:4-5), subrayando la severidad de la aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100224, 'spa', 'Lodo, cieno, barro', 'Lodo, cieno o barro (טִיט) — tierra húmeda en su estado crudo. El término abarca un espectro que va desde el cieno de las calles pisoteado con desprecio (Mi 7:10; Sal 18:42; Zac 9:3), pasando por el fango pegajoso de la cisterna de Jeremías (Jer 38:6) y el cieno metafórico de la angustia (Sal 40:2; 69:14), hasta el barro del alfarero y del fabricante de ladrillos moldeado para la construcción (Is 41:25; Nah 3:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100234, 'spa', 'Campamento, asentamiento', 'Un campamento, asentamiento o recinto amurallado, especialmente los campamentos circulares de tribus nómadas. En Génesis 25:16 las טִירוֹת de los hijos de Ismael se emparejan con חֲצֵרִים (''aldeas''), describiendo asentamientos nómadas semipermanentes. Números 31:10 lista טִירוֹת junto a ciudades que Israel destruyó en la guerra contra Madián. El Salmo 69:25 lo usa poéticamente como ''morada''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100236, 'spa', 'Almena, hilera de piedras', 'Una almena, parapeto o hilera de piedras en un contexto arquitectónico. En Cantares 8:9, טִירַת כֶּסֶף (''almena de plata'') es una metáfora para adornar o fortificar a la amada, un cambio notable respecto al sentido de campamento nómada. En Ezequiel 46:23 el plural טִירוֹת describe hileras o cursos de mampostería alrededor de los atrios interiores del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100241, 'spa', 'rocio, humedad nocturna', 'rocio, humedad nocturna');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100252, 'spa', 'Rocío del cielo', 'Rocío, específicamente el rocío del cielo (טַל שְׁמַיָּא), usado en las porciones arameas de Daniel como marcador recurrente de la exposición de Nabucodonosor a los elementos durante su locura decretada por Dios (Dn 4:15, 23, 25, 33; 5:21). La frase constructa siempre se combina con ''cielo'', subrayando que el rey más poderoso es humillado bajo el cielo abierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100253, 'spa', 'Manchado, moteado', 'Manchado, moteado o abigarrado — participio pasivo Qal que describe animales con marcas multicolores. Las siete apariciones se concentran en la narrativa de Jacob y Labán (Gn 30:32, 33, 35, 39; 31:10, 12), donde las cabras manchadas se emparejan con las «moteadas» (נָקֹד) y «listadas» (עָקֹד). Ez 16:16 extiende la imagen a santuarios idolátricos vistosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100254, 'spa', 'Remendado', 'Remendado — prendas o calzado reparado con parches, participio intensivo-pasivo del Pual. Aparece una sola vez en Jos 9:5 para describir el disfraz de los gabaonitas: llevaban «sandalias remendadas» (נְעָלוֹת מְטֻלָּאוֹת) para simular un largo viaje y engañar a Josué. El puente semántico con el sentido 1 es el concepto de una superficie con parches irregulares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100263, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que designa al cabeza ancestral de una familia de porteros levíticos en el Israel postexílico. Los hijos de Talmón figuran entre los porteros del templo que regresaron de Babilonia (Esd 2:42; Neh 7:45) y que servían en las puertas de Jerusalén (1 Cr 9:17; Neh 11:19; 12:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100264, 'spa', 'Qal: ser/volverse impuro', 'Qal estativo/incoativo: ser o volverse ritualmente impuro por contacto, condición o circunstancia. Es la acepción más frecuente (75 veces), dominante en Levítico 11-15, donde el contacto con cadáveres de animales (Lv 11:24-28), las emisiones corporales (Lv 15:18) y las enfermedades cutáneas provocan impureza automática hasta el atardecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100266, 'spa', 'Nifal: ser contaminado', 'Nifal reflexivo/medio-pasivo: llegar a estar contaminado, hallarse en estado de profanación. Aparece 19 veces, frecuentemente en contextos de impureza sexual (Nm 5:13-14, la prueba de la sotá, donde se cuestiona si la mujer «ha sido contaminada») y de apostasía nacional (Lv 18:24, donde las naciones «se contaminaron» con sus prácticas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100267, 'spa', 'Piel declarativo: declarar impuro', 'Piel declarativo-estimativo: declarar impuro, acto sacerdotal técnico de clasificación oficial. Restringido casi por completo a Levítico 13 (13 veces), donde el sacerdote examina afecciones cutáneas y «lo declarará impuro» (Lv 13:3, 8, 11, 15, 20). No es causación: el sacerdote no contamina, sino que pronuncia un veredicto autoritativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100268, 'spa', 'Hitpael: contaminarse', 'Hitpael reflexivo: contaminarse deliberadamente, sobre todo mediante contacto o prácticas prohibidas. Aparece 16 veces, predominantemente en contextos prohibitivos: «no os contaminéis» tocando muertos (Lv 11:24, 43), comiendo criaturas vedadas (Lv 11:43) o siguiendo costumbres paganas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100270, 'spa', 'Piel factitivo: contaminar', 'Piel factitivo: contaminar o hacer impuro, causando activamente la profanación de una persona, lugar u objeto. Abarca un amplio espectro moral-ritual (37 veces): Siquem contamina a Dina (Gn 34:5, 13, 27), Israel contamina la tierra mediante la idolatría (Jr 2:7) y el derramamiento de sangre profana el santuario (Lv 15:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100301, 'spa', 'Pual: contaminada (pasivo)', 'Forma Pual o pasiva aislada en Ez 4:14, donde Ezequiel protesta que nunca ha comido carne «contaminada». El uso adjetival describe carne ritualmente impura. Esta única ocurrencia se sitúa en la frontera entre el sistema verbal y el adjetivo טָמֵא, funcionando como referencia comprimida al entero sistema de impureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100335, 'spa', 'Ritual o moralmente impuro — Ceremonialmente impuro o moralmente contaminado, de', 'Ritual o moralmente impuro — Ceremonialmente impuro o moralmente contaminado, describiendo personas, animales, objetos o condiciones que quedan fuera de los límites de la pureza ritual según la legislación de la Torá. Cubre prohibiciones alimentarias (Lv 11:8), impureza corporal (Lv 13–15), contaminación por cadáver (Nm 19) y contaminación metafórica como los «labios impuros» de Isaías (Is 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100350, 'spa', 'impureza ritual o moral', 'impureza ritual o moral');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100375, 'spa', 'esconder, ocultar activamente', 'esconder, ocultar activamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100377, 'spa', 'estar escondido (estativo)', 'estar escondido (estativo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100378, 'spa', 'enterrar, sepultar en tierra', 'enterrar, sepultar en tierra');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100380, 'spa', 'cosa o lugar oculto', 'cosa o lugar oculto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100384, 'spa', 'esconderse (reflexivo)', 'esconderse (reflexivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100399, 'spa', 'Canasta agrícola', 'Canasta para transportar productos agrícolas, en particular frutos y primicias. En Deuteronomio 26:2, 4 contiene las primicias llevadas al santuario; en 28:5, 17 aparece en paralelo con la artesa de amasar como indicador del sustento cotidiano bajo bendición o maldición. El término designa un recipiente sencillo y funcional, probablemente tejido de mimbre o fibra vegetal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100402, 'spa', 'Gustar (literal)', 'Acto literal y gustativo de probar alimento o bebida: percibir el sabor llevando algo a la boca. Las apariciones abarcan contextos narrativos y poéticos: Jonatán probando la miel (1 S 14:29, 43), David rechazando el pan (2 S 3:35), Barzilai preguntando si aún puede saborear lo que come (2 S 19:35), los ninivitas con orden de no gustar alimento ni agua (Jon 3:7) y la célebre invitación del Salmo 34:8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100410, 'spa', 'Percibir, discernir (figurado)', 'Extensión figurada del gusto físico a la percepción mental o discernimiento por experiencia. En Proverbios 31:18 la mujer virtuosa «gusta» (percibe) que su comercio es bueno, evaluando por conocimiento directo y no por el paladar. Este salto metafórico del sentido gustativo al juicio está bien atestiguado en las lenguas semíticas y en las traducciones antiguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100411, 'spa', 'Gustar o alimentar', 'Gustar, probar o, en sentido causativo, hacer comer a alguien. En Daniel 4:25, 32 y 5:21 describe cómo Nabucodonosor era alimentado con hierba durante su período de locura. En Daniel 5:2, la expresión idiomática «en el gusto del vino» significa estar bajo la influencia del vino. El verbo abarca desde la alimentación literal hasta la experiencia sensorial del vino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100412, 'spa', 'Sabor, gusto', 'Sabor o gusto físico — la cualidad sensorial del alimento percibida por el paladar. El maná sabía a hojuelas con miel (Éx 16:31) y a torta de aceite fresco (Nm 11:8). Job 6:6 pregunta retóricamente si lo desabrido se puede comer sin sal. Jeremías 48:11 emplea el gusto figuradamente del vino de Moab cuyo sabor no ha cambiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100413, 'spa', 'Discernimiento, sensatez', 'Discernimiento, buen juicio o la facultad de sabiduría práctica. El טַעַם de Abigail en 1 S 25:33 es su consejo perspicaz que evitó que David derramara sangre. Proverbios 11:22 advierte que la belleza sin discreción es como anillo de oro en hocico de cerdo, y Proverbios 26:16 describe al perezoso como más sabio a sus propios ojos que siete que responden con טַעַם — con sensatez. Job 12:20 muestra a Dios quitando el discernimiento a los ancianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100414, 'spa', 'Conducta, comportamiento', 'Conducta exterior o modo de comportarse, especialmente tal como lo perciben los demás. En 1 S 21:14, David ''mudó su conducta'' (וַיְשַׁנּוֹ אֶת טַעְמוֹ) ante el rey filisteo, actuando como un demente para salvar su vida. El título del Salmo 34:1 hace referencia al mismo episodio. Aquí טַעַם ha pasado del juicio interior a su expresión visible — cómo uno se presenta ante otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100416, 'spa', 'Decreto, mandato', 'Decreto u orden oficial, reflejo de la influencia aramea. En Jonás 3:7, la proclamación sale מִטַּעַם הַמֶּלֶךְ — ''por decreto del rey''. Es el mismo uso que se encuentra ampliamente en Daniel y Esdras en pasajes arameos. El recorrido semántico de ''gusto'' a ''decreto'' pasa por ''juicio'': el criterio del rey sobre cómo deben ser las cosas se convierte en su resolución autoritativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100424, 'spa', 'Gusto literal, sensorial', 'El gusto en sentido literal y sensorial — la experiencia de saborear alimentos o vino. Aparece en Daniel 5:2, donde Belsasar, ''al gusto del vino'' (es decir, mientras lo disfrutaba), ordena traer los vasos del templo. Este es el significado raiz del cual se desarrollan las extensiones metaforicas hacia el juicio, la discrecion y el decreto oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100425, 'spa', 'Decreto, mandato — decreto real o gubernamental, edicto u orden oficial', 'Decreto, mandato — decreto real o gubernamental, edicto u orden oficial. Es el sentido dominante que abarca la gran mayoría de las ocurrencias en las secciones arameas de Esdras y Daniel. La correspondencia de Esdras gira en torno a decretos para detener y luego autorizar la construcción del templo (Esd 4:8-21; 5:3-17; 6:1-14; 7:13-23), mientras que Daniel registra el decreto de Nabucodonosor sobre la estatua de oro (Dn 3:10, 29) y el edicto de Darío (Dn 6:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100427, 'spa', 'Atención, consideración — respeto, atención o deferencia, usado en la expresión ', 'Atención, consideración — respeto, atención o deferencia, usado en la expresión aramea שִׂים טְעֵם עַל (''poner atención sobre''), que significa prestar atención o mostrar el debido respeto a un mandato o autoridad. En Daniel 3:12, los tres jóvenes judíos son acusados de no ''prestar atención'' al decreto de Nabucodonosor, y en Daniel 6:13 se acusa a Daniel de no mostrar ''consideración'' por el interdicto de Darío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100429, 'spa', 'Discreción, prudencia — discreción, prudencia o juicio sensato como facultad de ', 'Discreción, prudencia — discreción, prudencia o juicio sensato como facultad de la mente. Daniel 2:14 describe a Daniel respondiendo a Arioc, capitán de la guardia del rey, con ''consejo y discreción'' (עֵטָא וּטְעֵם). Esto preserva el sentido raíz del cognado hebreo טַעַם (''gusto, discernimiento'') y apunta a la etimología sensorial-cognitiva: así como el paladar discrimina sabores, la mente discrimina lo sabio de lo necio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100432, 'spa', 'pequenos, ninos pequenos', 'pequenos, ninos pequenos');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100457, 'spa', 'Palmo como medida', 'Palmo menor como unidad de medida lineal. Se emplea para describir el grosor del mar de bronce de Salomón, de un palmo de espesor (1 Re 7:26; 2 Cr 4:5). En el Salmo 39:5, el plural «palmos» se convierte en metáfora de la dolorosa brevedad de la vida. La unidad equivalía aproximadamente al ancho de cuatro dedos, unos 7-8 centímetros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100458, 'spa', 'Palmo menor (medida)', 'Un palmo menor (aproximadamente 7,4 cm), unidad estandar de medida lineal usada exclusivamente en contextos de arquitectura y mobiliario sagrados. Especifica el ancho del reborde de la mesa de los panes de la Proposicion (Ex 25:25; 37:12) y la medida extra anadida al codo comun para formar el codo largo en la vision del templo de Ezequiel (Ez 40:5; 43:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100460, 'spa', 'Embadurnar con falsedad', 'Enlucir, embadurnar o recubrir, especialmente con falsedad. Job 13:4 condena a sus amigos como «embadurnadores de mentira», cubriendo la verdad con engaños. Job 14:17 (texto difícil) podría referirse a enlucir la transgresión, sellándola. Salmo 119:69 se lamenta de que «los soberbios me han embadurnado de mentira», manchando la reputación del salmista. La asociación constante con el engaño y el encubrimiento hace de este verbo una imagen poderosa de la falsificación deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100467, 'spa', 'Expulsar o echar', 'Echar fuera o expulsar a alguien de su lugar o comunidad. Las cuatro ocurrencias aparecen en Daniel (4:25, 32, 33; 5:21) y describen la expulsión de Nabucodonosor de la sociedad humana para vivir entre animales salvajes. El participio activo en Daniel 4:25, 32 conlleva fuerza profética («te echarán»), mientras que el perfecto pasivo en 4:33 y 5:21 relata el juicio cumplido («fue echado»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100472, 'spa', 'Antes (temporal) — Adverbio o conjunción temporal que significa «antes de que» o', 'Antes (temporal) — Adverbio o conjunción temporal que significa «antes de que» ocurra un evento. Este es el uso abrumadoramente mayoritario (51 de 57 ocurrencias), que rige verbos en imperfecto para establecer secuencia: «antes de que se acostaran» (Gn 19:4), «antes de que él terminara de hablar» (Gn 24:15). El español «antes de que» traduce consistentemente esta precedencia temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100477, 'spa', 'Aún no, todavía no — Adverbio que significa «todavía no», indicando que una acci', 'Aún no, todavía no — Adverbio que significa «todavía no», indicando que una acción o estado esperado no se ha realizado. En Éxodo 9:30, Moisés dice a los siervos de Faraón «todavía no teméis al SEÑOR», y en 1 Samuel 3:7 el niño Samuel «aún no conocía al SEÑOR». Este sentido aparece frecuentemente en el diálogo, dando urgencia: la brecha entre lo que debería ser y lo que aún no es.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100481, 'spa', 'Delante de (espacial) — Una rara extensión espacial que significa «delante de» o', 'Delante de (espacial) — Una rara extensión espacial que significa «delante de» o «en presencia de», atestiguada solo en el Salmo 5:5, donde los malvados no permanecerán טֶרֶם ante los ojos del salmista (o ante Dios). Sin embargo, la mayoría de los comentaristas tratan este caso como fundamentalmente temporal, lo que hace de este un sentido marginal debatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100483, 'spa', 'Ser despedazado, ser presa — Nifal y Qal pasivo', 'Ser despedazado, ser presa — Nifal y Qal pasivo: ser desgarrado, ser víctima de depredación. Génesis 37:33 y 44:28 emplean la construcción enfática del infinitivo absoluto טָרֹף טֹרַף para expresar certeza y dolor. Éxodo 22:13 lo aplica a la ley ganadera: si un animal es despedazado, los restos sirven como evidencia. La voz pasiva centra a la víctima en lugar del depredador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100484, 'spa', 'Desgarrar, despedazar, devorar — Qal activo', 'Desgarrar, despedazar, devorar — Qal activo: desgarrar, despedazar o hacer presa, el sentido depredador central. Se usa literalmente de fieras (Gn 49:27, Dt 33:20) y figuradamente de enemigos (Job 16:9, 18:4) y de Dios mismo (Os 5:14, Sal 50:22). La imagen es cruda y cinética: garras y dientes desgarrando carne. El verbo evoca la violencia bruta del ataque animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100503, 'spa', 'Alimentar, proveer sustento — Hifil causativo en Proverbios 30', 'Alimentar, proveer sustento — Hifil causativo en Proverbios 30:8: הַטְרִיפֵנִי לֶחֶם חֻקִּי — ''aliméntame con el pan que me corresponde''. Aquí la raíz depredadora se domestica en provisión y sustento. El puente semántico pasa por la idea de conseguir alimento: lo que el león desgarra para sus cachorros se convierte en lo que Dios provee para su siervo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100504, 'spa', 'Presa desgarrada por un depredador, especialmente un león, y por extensión el bo', 'Presa desgarrada por un depredador, especialmente un león, y por extensión el botín violento o despojo tomado por conquistadores. La evidencia multilingüe es consistente: español presa, francés proie, alemán Raub convergen en la imagen de carne arrebatada. Jacob bendice a Judá como un león agazapado sobre su presa (Gn 49:9), y Nahúm acusa a Nínive como ciudad de rapiña (Nah 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100505, 'spa', 'Alimento o provisión en un sentido doméstico y no violento, extendiendo la idea ', 'Alimento o provisión en un sentido doméstico y no violento, extendiendo la idea de lo que sustenta la vida desde la presa cazada hasta el sustento general. El Salmo 111:5 lo asocia con la fidelidad al pacto, Proverbios 31:15 con la mujer hacendosa del hogar, y Malaquías 3:10 con el almacén de bendición. Las traducciones confirman el desplazamiento de la depredación a la provisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100511, 'spa', 'Hoja fresca o follaje verde, atestiguado una sola vez en Ezequiel 17', 'Hoja fresca o follaje verde, atestiguado una sola vez en Ezequiel 17:9, donde el plural constructo describe hojas arrancadas de una vid trasplantada. El vínculo semántico con la idea raíz de arrancar o desgarrar sigue visible, aunque el referente se ha desplazado de la carne animal a la vida vegetal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100513, 'spa', 'Animal despedazado', 'Animal desgarrado por fieras, o la carne resultante, ritualmente prohibida como alimento. Aparece emparejado con nebelá («animal muerto naturalmente») como conjuntamente prohibidos (Lv 7:24; 17:15; 22:8; Ez 4:14; 44:31). Éxodo 22:13, 31 establecen las regulaciones pastoriles y dietéticas. La protesta de Jacob a Labán (Gn 31:39) revela la responsabilidad del pastor por pérdidas de depredación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100524, 'spa', 'Nombre propio personal', 'Jaazanías, nombre propio que significa ''Yahvé escucha'', usado para varios individuos distintos. En 2 Reyes 25:23, un oficial militar judío que se sometió a Gedalías tras la caída de Jerusalén. En Ezequiel 8:11, un hijo de Safán que dirigía a los ancianos en culto clandestino con incienso. En Jeremías 35:3, un hijo de Jeremías el recabita. En Ezequiel 11:1, un hijo de Azur entre quienes daban consejo perverso en Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100525, 'spa', 'Jair (nombre propio)', 'Nombre propio Jair (יָאִיר, ''él ilumina''), portado por varios personajes bíblicos: (1) Jair hijo de Manasés, quien capturó aldeas en Galaad y las renombró Havot-Jair (Nm 32:41; Dt 3:14; Jos 13:30; 1 R 4:13; 1 Cr 2:22-23); (2) un juez menor en Galaad cuyos treinta hijos controlaban treinta ciudades (Jue 10:3-5); y (3) el padre de Mardoqueo (Est 2:5). El significado teofórico ''él da luz'' sugiere iluminación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100529, 'spa', 'Necedad culpable', 'Obrar neciamente de manera moralmente culpable, donde la insensatez equivale a pecado. En Números 12:11, Aarón empareja este verbo con ''pecamos'', confesando tanto necedad como transgresión por oponerse a Moisés. Jeremías 5:4 atribuye tal conducta insensata a la ignorancia del pueblo común respecto a las ordenanzas de Dios. Este sentido enfatiza la necedad deliberada y moralmente responsable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100530, 'spa', 'Determinar, resolver, emprender', 'Determinar, resolver, emprender: determinar, resolver o emprender el inicio de una acción significativa, enfatizando la iniciativa decidida más que la mera disposición. Moisés ''emprendió'' la exposición de la Torá al otro lado del Jordán (Deut 1:5), los cananeos y amorreos ''se empeñaron'' en mantener su territorio (Jos 17:12; Jue 1:27, 35), y Saúl ''se dispuso'' a ponerse la armadura de David (1 Sam 17:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100531, 'spa', 'Estar dispuesto, consentir', 'Estar dispuesto, consentir: estar dispuesto, consentir o tener a bien hacer algo, expresando acuerdo voluntario o conformidad para emprender una acción. Este sentido dominante (12 apariciones) abarca desde Moisés que ''consintió en habitar'' con Jetro (Éx 2:21) hasta el levita que ''consintió en quedarse'' como sacerdote doméstico (Jue 17:11), y Dios que ''no quiso'' destruir a su pueblo (1 Sam 12:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100533, 'spa', 'Atreverse, osar', 'Atreverse, osar: atreverse u osar hacer algo presuntuoso, con un matiz de audacia humilde ante un superior. Solo 2 apariciones, pero ambas se encuentran entre los diálogos más memorables del Génesis: Abraham intercediendo por Sodoma dice ''me he atrevido a hablar a mi Señor, aunque soy polvo y ceniza'' (Gén 18:27) y repite ''no se enoje mi Señor y me atreveré a hablar una vez más'' (Gén 18:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100545, 'spa', 'El río Nilo — El río Nilo como nombre propio', 'El río Nilo — El río Nilo como nombre propio: el gran río de Egipto, centro de la narrativa del Éxodo y los oráculos proféticos. Las 47 ocurrencias incluyen el sueño de Faraón (Gn 41:1-3), la plaga de sangre (Éx 7:20-21), al infante Moisés puesto entre los juncos (Éx 2:3) y el juicio profético contra Egipto (Is 19:5-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100548, 'spa', 'Río, corriente — Sustantivo común que significa «río» o «corriente», usado con s', 'Río, corriente — Sustantivo común que significa «río» o «corriente», usado con sufijos posesivos o en plural para designar grandes cursos de agua más allá del cauce específico del Nilo. Ezequiel 29:3 tiene a Faraón declarando «mi río», y el Salmo 78:44 recuerda cómo Dios «convirtió sus ríos en sangre». Esto incluye «los ríos de Egipto» de Isaías 7:18 como designación geográfica genérica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100555, 'spa', 'Canal, acequia — Canales, acequias de riego o cursos de agua artificiales, que r', 'Canal, acequia — Canales, acequias de riego o cursos de agua artificiales, que reflejan las ramificaciones del delta y la infraestructura construida de la hidrología egipcia. Éxodo 7:19 y 8:5 enumeran יְאוֹרִים junto a otros elementos acuáticos (ríos, estanques, pozas), e Isaías 19:6 predice que los «canales» apestarán. Job 28:10 usa la palabra para canales tallados en la roca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100569, 'spa', 'Desesperar, perder esperanza', 'Desesperar, quedarse sin esperanza, rendirse, en la conjugación Nifal. El participio נוֹאָשׁ funciona casi como interjección en Jeremías (''¡Es inútil!'' Jer 2:25; 18:12), expresando un fatalismo desafiante. En 1 Sam 27:1, David espera estratégicamente que Saúl ''se desespere'' de encontrarlo. Job 6:26 se dirige a Job como ''el desesperado''. Designa una condición de abandono total de la esperanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100572, 'spa', 'Causar desesperación', 'Hacer que alguien se desespere, provocar desaliento, en la conjugación Piel (causativa). Atestiguado únicamente en Ecl 2:20, donde Qohélet deliberadamente hace desesperar a su propio corazón respecto a todo su trabajo. El hecho de que el objeto sea su propio corazón intensifica el patetismo. El español ''para desesperar'' preserva bien la fuerza causativa de esta forma verbal poco frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100574, 'spa', 'Josías, rey de Judá — el nombre propio Yoshiyahu (Josías), referido al hijo de A', 'Josías, rey de Judá — el nombre propio Yoshiyahu (Josías), referido al hijo de Amón que reinó como rey de Judá aproximadamente del 640 al 609 a.C. Nombrado proféticamente una generación antes de su nacimiento (1 Re 13:2), es célebre por las reformas deuteronómicas del 621 a.C. (2 Re 22–23) y recordado como el rey que se volvió al SEÑOR con todo su corazón, alma y fuerzas (2 Re 23:25). Las 53 apariciones corresponden a este único portador del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100579, 'spa', 'Producto, rendimiento', 'El producto o rendimiento del suelo (יְבוּל), referido a la cosecha de tierra cultivada. Casi todas las ocurrencias aparecen en la fórmula ''la tierra da su fruto'', ya sea en bendición del pacto (Lv 26:4; Sal 67:6; 85:12; Ez 34:27; Zac 8:12) o en su retención como maldición (Dt 11:17; Lv 26:20; Hag 1:10). Habacuc 3:17 lo acota al fruto de la vid, mientras que Job 20:28 lo extiende metafóricamente a los bienes de la casa del impío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100585, 'spa', 'Nombre predavídico de Jerusalén', 'El nombre preisraelita de Jerusalén, empleado cuando el texto identifica deliberadamente la ciudad con su herencia jebusea. Cada aparición empareja Jebús con Jerusalén mediante una glosa explicativa (''Jebús, que es Jerusalén''), como en Jueces 19:10–11 y 1 Crónicas 11:4–5. Las traducciones multilingües transliteran de forma consistente en vez de traducir, reflejando su condición de topónimo opaco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100586, 'spa', 'jebuseo (gentilicio)', 'jebuseo (gentilicio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100599, 'spa', 'Hijo de David', 'Ibhar, hijo de David nacido en Jerusalén. 2 Samuel 5:15 lo incluye entre los hijos nacidos a David en Jerusalén tras el traslado de la capital desde Hebrón. 1 Crónicas 3:6 y 14:5 ofrecen referencias paralelas en la genealogía davídica. El significado del nombre, «Él elige», sugiere elección divina o acción de gracias por su nacimiento. La ausencia de más relatos sobre Ibhar refleja la oscuridad de la mayoría de los hijos reales que no figuraron en la sucesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100600, 'spa', 'Jabín, rey cananeo', 'Jabín (יָבִין), nombre real o título dinástico de reyes cananeos que gobernaban desde Hazor. El nombre deriva de la raíz ב-י-ן (''discernir, entender''). Dos personajes llevan este nombre: el rey derrotado por Josué en la campaña del norte (Jos 11:1), y el rey posterior cuyo comandante Sísara fue derrotado por Barac y muerto por Jael (Jue 4:2, 7, 17, 23, 24). La recurrencia del nombre sugiere una convención dinástica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100602, 'spa', 'Ser guiado, ser conducido (Hofal pasivo)', 'Ser guiado, ser conducido (Hofal pasivo): pasivo Hofal que denota ser guiado o conducido a lo largo de un camino, con énfasis en la dirección y el acompañamiento. Salmo 45:14-15 describe a la novia real siendo conducida ante el rey, mientras que Isaías 53:7 retrata al siervo siendo llevado al matadero. Destaca la cualidad pasiva y deliberada del movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100603, 'spa', 'Traer, llevar (Hifil activo)', 'Traer, llevar (Hifil activo): causativo Hifil activo que significa traer, guiar o llevar a alguien o algo hacia un destino, a menudo con dignidad procesional. Salmo 68:29 imagina a reyes trayendo ofrendas al templo, y Salmo 76:11 llama a las naciones circundantes a presentar tributos. Refleja tanto la dimensión direccional como la de transporte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100604, 'spa', 'Ser transportado, ser traído (Hofal pasivo)', 'Ser transportado, ser traído (Hofal pasivo): pasivo Hofal con énfasis en ser cargado o transportado como objeto pasivo, subrayando el traslado más que la guía personal. En Oseas 10:6, el tributo es llevado a Asiria; en Job 10:19, Job desea haber sido llevado directamente del vientre a la tumba. La distinción con el sentido 2 radica en la cualidad impersonal del transporte, como carga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100616, 'spa', 'Traer o transportar', 'Traer o llevar (Hafel arameo). Esdras 5:14 relata que Ciro «sacó» los utensilios del templo de Babilonia. Esdras 6:5 ordena que los vasos de oro y plata «sean devueltos» a Jerusalén. Esdras 7:15 menciona llevar plata y oro «a Jerusalén» para el templo. El contexto constante involucra el transporte de vasos sagrados de regreso a su lugar legítimo, subrayando la restauración mediante la acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100620, 'spa', 'Ciudad de Manasés', 'Ibleam, ciudad en el territorio de Manasés dentro de la región de Jezreel. Josué 17:11 la enumera entre las ciudades de Manasés en territorios de otras tribus. Jueces 1:27 registra el fracaso de Manasés en desposeer a los cananeos de Ibleam. 2 Reyes 9:27 sitúa la herida mortal de Ocozías «en la subida de Ibleam» durante el golpe de Jehú. Equivale a Bileam en 1 Crónicas 6:55.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100621, 'spa', 'Deber de levirato', 'Cumplir el deber de levirato desposando a la viuda del hermano fallecido. Génesis 38:8 registra la orden de Judá a Onán: «Únete a la esposa de tu hermano y cumple con ella tu deber de cuñado». Deuteronomio 25:5 legisla: «su cuñado cumplirá con ella el deber de levirato». Deuteronomio 25:7 permite la negativa: «si el cuñado se niega a cumplir el deber de levirato conmigo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100623, 'spa', 'Cunada (levirato)', 'Esposa del hermano o cunada, dentro del marco del matrimonio levirato, donde el hermano del difunto debe desposar a la viuda y suscitar descendencia en su nombre. En Deuteronomio 25:7-9, el termino aparece tres veces en el procedimiento legal de rechazo, incluida la ceremonia de quitar la sandalia. En Rut 1:15, Noemi lo aplica a Orfa como concunada de Rut.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100628, 'spa', 'Jaboc, río transjordano', 'Nombre propio del río Jaboc (יַבֹּק), afluente transjordano del Jordán identificado con el moderno río Zarqa. Posee significado tanto narrativo como geopolítico: es el sitio donde Jacob luchó con Dios toda la noche junto al vado (Gn 32:22-23), y se cita repetidamente como frontera entre los territorios amorreo, amonita e israelita (Nm 21:24; Dt 2:37; 3:16; Jos 12:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100632, 'spa', 'Ser avergonzado — el sentido metafórico del Hifil donde la humillación social se', 'Ser avergonzado — el sentido metafórico del Hifil donde la humillación social se compara con el marchitarse físico. Jeremías pregunta ''¿se avergonzaron?'' (Jer 6:15; 8:12) usando esta misma raíz, y 2 Sam 19:5 relata que los hombres de Joab fueron ''avergonzados''. La conexión entre secarse y la vergüenza reside en el visible encogimiento y pérdida de vitalidad que ambas experiencias comparten.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100633, 'spa', 'Estar seco, marchitarse (intransitivo) — el sentido intransitivo general de volv', 'Estar seco, marchitarse (intransitivo) — el sentido intransitivo general de volverse seco, secarse o marchitarse, dicho de fuentes de agua (Gn 8:7, 14), vegetación (Is 19:7; Ez 17:10), huesos (Ez 37:11) y manos (1 Re 13:4). Es el uso del Qal y Nifal donde no se nombra un agente externo; las cosas simplemente pierden su humedad y vitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100634, 'spa', 'Hacer secar (causativo) — el sentido causativo (Hifil y Piel) de hacer que algo ', 'Hacer secar (causativo) — el sentido causativo (Hifil y Piel) de hacer que algo se seque: Dios secando el mar Rojo (Jos 2:10), el Jordán (Jos 4:23) o los ríos de Egipto (Is 19:5). El sujeto es típicamente Dios ejerciendo poder soberano sobre el agua y la vegetación, ya sea en juicio o liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100674, 'spa', 'seco, marchito', 'Seco, reseco o marchito: describe algo que ha perdido su humedad o vitalidad. Se usa literalmente de las uvas secas prohibidas a los nazareos (Nm 6:3) y figuradamente del agotamiento existencial (''nuestra alma está reseca'', Nm 11:6). Ezequiel lo emplea poderosamente para los huesos secos que esperan resurrección (37:2, 4) y la parábola del árbol seco frente al verde de la casa davídica (17:24; 21:3). Isaías 56:3 lo aplica al eunuco que se considera estéril.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100679, 'spa', 'Nombre propio Jabes (יָבֵשׁ / יָבֵישׁ), usado principalmente como topónimo de Ja', 'Nombre propio Jabes (יָבֵשׁ / יָבֵישׁ), usado principalmente como topónimo de Jabes de Galaad en Transjordania y secundariamente como patronímico. La ciudad es central en tres narrativas fundamentales: la obtención de esposas benjaminitas tras la guerra civil (Jue 21:8-14), la heroica liberación por parte de Saúl del asedio amonita (1 Sam 11:1-11) y la leal recuperación de los restos de Saúl por sus agradecidos ciudadanos (1 Sam 31:11-13). Como nombre personal, Jabes es el padre de Salum, rey usurpador del reino del norte (2 Re 15:10-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100687, 'spa', 'Tierra seca, suelo firme', 'Tierra seca o suelo firme (יַבָּשָׁה), usado en oposición al agua o al mar. Aparece en tres grandes núcleos temáticos: (a) la creación, donde la tierra seca emerge de las aguas reunidas (Gn 1:9–10); (b) las narrativas de salvación a través del agua, donde Dios provee un camino seco por el Mar Rojo (Éx 14:16, 22, 29; 15:19; Neh 9:11; Sal 66:6) y el Jordán (Jos 4:22); y (c) la historia de Jonás, donde el profeta reconoce a Dios como creador del mar y la tierra seca (Jon 1:9; 2:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100697, 'spa', 'Nombre personal', 'Nombre personal «Igal» o «Yigal» (Él redime), portado por tres individuos. Números 13:7 identifica a Igal hijo de José, de Isacar, como uno de los espías. 2 Samuel 23:36 enumera a Igal hijo de Natán entre los guerreros de élite de David. 1 Crónicas 3:22 incluye a Yigal entre los descendientes de Zorobabel en la genealogía real postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100702, 'spa', 'causar aflicción (causativo)', 'Causar dolor, afligir o atormentar a alguien: las formas causativas Hifil y Piel. El agente inflige activamente sufrimiento sobre otro. Dios ''no aflige ni entristece de corazón a los hijos de los hombres'' (Lm 3:33, Piel), pero ''ha afligido'' a Jerusalén (Lm 1:5, 12; 3:32, Hifil). Job clama a sus amigos ''¿hasta cuándo me atormentaréis?'' (Job 19:2), e Isaías nombra a los opresores como ''los que te afligen''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100705, 'spa', 'estar afligido (pasivo)', 'Estar afligido, experimentar tristeza: la forma Nifal pasivo-reflexiva. El sujeto padece el dolor en vez de causarlo. Lamentaciones 1:4 describe a las vírgenes de Sion como נוּגוֹת (''afligidas''), emparejadas con sacerdotes que gimen y amargura por todas partes. Sofonías 3:18 habla de los נוּגֵי מִמּוֹעֵד (''entristecidos por las fiestas solemnes''), exiliados que lloran las festividades que ya no pueden celebrar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100710, 'spa', 'Tristeza, pesar, angustia', 'Tristeza o pesar emocional profundo, un estado persistente de aflicción más que una punzada momentánea. Se empareja con אֲנָחָה (''suspiro'') en Isaías 35:10 y 51:11, con צָרָה (''angustia'') en Salmo 116:3, y se contrapone a שִׂמְחָה (''gozo'') en Ester 9:22. El dolor anticipado de Jacob ante la pérdida de Benjamín (Gn 42:38; 44:31) le confiere una dimensión visceral y paternal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100719, 'spa', 'Trabajo, labor, esfuerzo', 'Trabajo, labor, esfuerzo: el acto de trabajo laborioso, afán o esfuerzo extenuante, enfatizando el dolor del empeño involucrado. Jacob lo usa para describir sus años de servicio agotador bajo Labán (Gén 31:42, emparejado con עֳנִי, aflicción). En Deuteronomio 28:33, la palabra designa el trabajo propio que opresores extranjeros devorarán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100720, 'spa', 'Producto del trabajo, ganancia', 'Producto del trabajo, ganancia: el fruto, producción, ganancia o bienes adquiridos como resultado del propio esfuerzo, una extensión metonímica del trabajo a su resultado. Job 39:16 lo usa para la labor del avestruz (sus huevos/crías), Salmo 109:11 para las ganancias de un hombre embargadas por acreedores, y Jeremías 20:5 para la riqueza acumulada de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100732, 'spa', 'Esfuerzo activo en el trabajo o la labor, donde el énfasis recae en la lucha más', 'Esfuerzo activo en el trabajo o la labor, donde el énfasis recae en la lucha más que en el cansancio. Josué recuerda a Israel que disfrutan de ciudades «por las que no trabajaron» (Jos 24:13); el Siervo de Isaías lamenta: «En vano me he fatigado» (Is 49:4). La distinción con el sentido 1 es sutil pero consistente: aquí se subraya el proceso de esforzarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100733, 'spa', 'Estado intransitivo de agotamiento físico o emocional', 'Estado intransitivo de agotamiento físico o emocional. El guerrero de David, Eleazar, luchó hasta que su mano «se cansó» (2 Sam 23:10); el salmista está «cansado de gemir» (Sal 6:6). Las traducciones multilingües confirman el enfoque en la condición resultante más que en la actividad: estar agotado, exhausto, consumido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100739, 'spa', 'Hifil causativo', 'Hifil causativo: hacer que alguien se canse, fatigar o exasperar a otra persona. Tiene gran peso teológico: Dios se queja de que Israel lo ha «cansado» no con ofrendas sino con pecados (Is 43:24), y Malaquías pregunta dos veces «¿En qué lo hemos cansado?» (Mal 2:17). El español «cansasteis» refuerza la fuerza causativa e interpersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100740, 'spa', 'Sentido intensivo Piel', 'Sentido intensivo Piel: agotar a alguien mediante una acción persistente o repetida. En Eclesiastés 10:15, el trabajo del necio «lo fatiga» porque no sabe llegar a la ciudad, una imagen irónica del esfuerzo que se acumula sobre sí mismo. Josué 7:3 aconseja no fatigar a todo el pueblo por una batalla menor. El tronco intensivo sugiere un proceso de desgaste más que un solo acto de agotamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100755, 'spa', 'Cansado o fatigoso', 'Cansado, agotado o fatigoso. Deuteronomio 25:18 recuerda que Amalec atacó a Israel cuando estaban «cansados y agotados» en el desierto. 2 Samuel 17:2 describe a David como «cansado y débil de manos», vulnerable al ataque. Eclesiastés 1:8 declara filosóficamente que «todas las cosas son fatigosas», todo está lleno de trabajo. El rango semántico abarca la fatiga física y el cansancio existencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100757, 'spa', 'Temer, recelar', 'Tener miedo, sentir pavor — expresando aprension temerosa ante una amenaza concreta. Se construye con מִפְּנֵי (''ante la presencia de'') para el objeto temido, sea la ira divina (Dt 9:19) o una enfermedad catastrofica (Dt 28:60). En Job 3:25 y 9:28, el temor es pavor existencial ante el sufrimiento. El salmista teme el oprobio (Sal 119:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100759, 'spa', 'mano física (cuerpo)', 'La mano literal como parte del cuerpo, variante que enfatiza el aspecto puramente físico sin extensión metafórica de poder o agencia. Incluye contextos donde la mano aparece en acciones corporales directas: tomar, dar, extender, lavar. Complementa el sentido 1 al centrarse en la concreción anatómica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100816, 'spa', 'conforme a los medios de', 'Construcción preposicional idiomática (כְּיַד) que significa ''conforme a los medios/la provisión/la capacidad de''. Se usa casi exclusivamente en Esdras-Nehemías para la provisión divina: ''conforme a la buena mano de su Dios sobre él'' (Esd 7:6, 9, 28; 8:18; Neh 2:8). Extiende metafóricamente la capacidad de la mano hacia la idea de lo que uno puede proveer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100820, 'spa', 'espiga, clavija (ensamblaje)', 'Término técnico arquitectónico para la espiga o clavija saliente que une las tablas del tabernáculo. Circunscrito a las narrativas de construcción del tabernáculo (Éx 26:17-19; 36:22-24). La proyección con forma de mano que encaja en una mortaja da a este sentido su lógica etimológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100824, 'spa', 'lado, orilla, junto a', 'Extensión espacial que significa ''lado, orilla, junto a''. Las glosas multilingües pasan de ''mano'' a ''lado'': español ''al lado de'', hindi किनारे, coreano 곁/옆. La hija del Faraón estaba ''a la orilla'' del Nilo (Éx 2:5) y los cananeos habitaban ''junto al'' mar (Nm 13:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100828, 'spa', 'asa, brazo de trono', 'Asa de un recipiente, soporte de eje o brazo de un trono, extendiendo la metáfora de la mano al ámbito mecánico. Se encuentra en las bases de bronce del templo de Salomón (1 R 7:33-36) y en los brazos de su trono de marfil (1 R 10:19; 2 Cr 9:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100829, 'spa', 'puesto, posición', 'Tres apariciones ambiguas que probablemente significan ''puesto'' o ''posición''. En Nm 2:17 (''cada uno en su lugar'') emerge el sentido espacial-posicional. En 2 R 7:2, 17 (''el capitán sobre cuya mano se apoyaba el rey''), las versiones francesa y alemana confirman la lectura de ''puesto asignado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100880, 'spa', 'poder de la espada', 'Una única aparición en Sal 63:10 (63:11 en versiones en español) donde ''la mano de la espada'' significa ''el poder de la espada''. Este uso militar-destructivo es una extensión natural del modismo mano-como-poder hacia el sentido abstracto de fuerza o instrumento bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100884, 'spa', 'mano (parte del cuerpo) — La mano fisica y, por metonimia, poder, posesion o ins', 'mano (parte del cuerpo) — La mano fisica y, por metonimia, poder, posesion o instrumentalidad: el cognado arameo del hebreo yad, restringido a Daniel y Esdras. Se usa literalmente para la mano milagrosa que escribe en la pared en el banquete de Belsasar (Dan 5:5, 24) y la piedra cortada ''sin manos'' (Dan 2:34, 45) que significa agencia divina aparte del esfuerzo humano. Las construcciones preposicionales expresan custodia y control.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100898, 'spa', 'Echar suertes', 'Describe el acto literal de echar suertes (גורל) para repartir botín o cautivos. Aparece en textos proféticos que condenan a naciones enemigas por tratar al pueblo de Dios como mercancía repartida al azar. Las glosas interlingüísticas enfatizan el movimiento de lanzar, distinguiendo esta rara forma de otros términos para el sorteo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100900, 'spa', 'Dar gracias, alabar (Hifil)', 'La acepción dominante del Hifil, con 94 de 114 ocurrencias: dar gracias a Dios o alabarlo. Es el verbo de los grandes salmos de acción de gracias (Sal 107:1; 118:1; 136:1: «Dad gracias a Yahvé, porque es bueno») y del nombramiento davídico de cantores levíticos (1 Cr 16:7-8). El causativo Hifil transforma la raíz en un acto de proclamación pública.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100909, 'spa', 'Confesar pecado (Hitpael)', 'El Hitpael reflexivo, usado 11 veces para describir la confesión personal o comunitaria de pecado. Levítico lo emplea para el ritual del Día de la Expiación, donde Aarón confiesa sobre el macho cabrío (Lv 16:21), y para las ofrendas individuales por culpa (Lv 5:5). La forma reflexiva implica autoexamen: volver hacia uno mismo el acto declarativo de יָדָה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100912, 'spa', 'Reconocer culpa (Hifil)', 'Un uso del Hifil donde el sentido pasa de la alabanza a la confesión o el reconocimiento del pecado, como en 1 Re 8:33-35 (la oración de Salomón) y Sal 32:5 («Mi pecado te declaré»). Estas 6 ocurrencias muestran que el Hifil puede significar ''reconocer, admitir'' cuando el objeto es la transgresión en lugar de la bondad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100934, 'spa', 'Arrojar, derribar (Piel)', 'La rara conjugación Piel que conserva el significado físico originario de יָדָה: arrojar o derribar. Solo dos casos claros sobreviven: Lm 3:53 («arrojaron mi vida en el foso») y Zac 1:21 («para derribar los cuernos»). El etiópico ወደየ retiene con mayor amplitud este sentido concreto de lanzamiento, que subyace a toda la evolución semántica de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100940, 'spa', 'Disparar (extensión bélica)', 'Una única ocurrencia en Jr 50:14, donde el sentido parece ser ''disparar'' (flechas), como extensión del significado de arrojar. Se trata como una orden militar. Este uso tiende un puente con la acepción Piel de ''lanzar'' y puede representar un empleo arcaico o dialectal de la raíz en contexto bélico: lanzar proyectiles contra Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100957, 'spa', 'Nombre propio', 'Nombre personal de etimología incierta, presente en contextos genealógicos y postexílicos. La variación textual (Ido/Yadai/Yadav) y la aparición de «su mano» en algunas glosas sugieren que los escribas a veces confundieron este nombre raro con la palabra común para «mano» (יד), lo que evidencia la ambigüedad en la tradición manuscrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100959, 'spa', 'Nombre propio', 'Nombre que designa liderazgo en la comunidad restaurada. El sumo sacerdote Jadúa es especialmente notable por haber servido durante la transición al dominio griego, lo que convierte este nombre en un marcador histórico. Las variantes textuales en distintos manuscritos sugieren que el nombre era fonológicamente difícil o experimentó estandarización ortográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100960, 'spa', 'Jedutun (nombre propio) — El nombre personal Jedutun (יְדוּתוּן / יְדֻתוּן / יְד', 'Jedutun (nombre propio) — El nombre personal Jedutun (יְדוּתוּן / יְדֻתוּן / יְדִיתוּן), que identifica a un maestro de coro levita designado por David. Las 20 apariciones se encuentran en Cronicas, Nehemias y titulos de Salmos. Las variaciones ortograficas (con y sin yod, con holam o qibbuts) reflejan fluidez dialectal o escribal, no personas distintas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100968, 'spa', 'amado, ser querido', 'Amado, querido, hermoso: expresa profundo afecto o deleite estético en un registro poético. Usado sustantivamente de personas amadas por Dios o por el hablante: Benjamín es ''el amado de YHWH'' (Dt 33:12); el profeta se dirige a YHWH como ''mi amado'' en el cántico de la viña (Is 5:1); los ''amados'' del salmista son aquellos que Dios libra (Sal 60:7; 108:7); y Dios da a su amado el sueño (Sal 127:2). El femenino plural יְדִידוֹת funciona como sustantivo abstracto en el título del Salmo 45.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100977, 'spa', 'Yediael', 'Nombre propio Yediael (יְדִיעֲאֵל, ''conocido de Dios''), usado para tres o más individuos en Crónicas: un ancestro benjaminita de un clan guerrero (1 Chr 7:6, 10, 11), uno de los valientes de David que posiblemente sea también el capitán manasita de 1 Chr 12:21, y un portero coraíta (1 Chr 26:2). En español se traduce comúnmente como ''Jediael'' o ''Yediael''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100980, 'spa', 'Qal: conocer, saber', 'Sentido abrumadoramente mayoritario: conocimiento cognitivo que abarca hechos, situaciones y verdad. Éxodo 7:5 (''los egipcios conocerán que yo soy el SEÑOR'') ejemplifica el reconocimiento mediante la acción divina. Las glosas multilingües convergen en ''conocer/saber'' (español), ''connaître/savoir'' (francés), ''erkennen/wissen'' (alemán).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101010, 'spa', 'conocedor, el que sabe', 'Participio activo Qal como sustantivo: ''conocedor,'' ''el que sabe,'' ''conocido.'' Génesis 3:5 lo emplea participialmente (''conocedores del bien y del mal''), mientras los Salmos hablan de ''mis conocidos.'' El cambio participial-sustantival se confirma en las equivalencias multilingües.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101012, 'spa', 'conocer a una persona', 'Conocimiento relacional y experiencial de personas: reconocer, estar familiarizado, tener trato íntimo. Deuteronomio 34:10 habla de Moisés a quien ''el SEÑOR conoció cara a cara.'' No se trata de saber datos sobre alguien, sino de conocerlo personalmente, marcado por el complemento directo de persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101017, 'spa', 'Hifil: dar a conocer', 'Hifil causativo: ''dar a conocer,'' ''informar,'' ''enseñar.'' En Génesis 41:39 Dios da a conocer a José el significado del sueño. La perífrasis española ''dar a conocer'' y la francesa ''faire connaître'' calcan con precisión la morfología causativa hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101019, 'spa', 'infinitivo absoluto enfático', 'Infinitivo absoluto usado adverbialmente para énfasis: ''ciertamente saber,'' ''a sabiendas.'' En 1 Samuel 20:3 David jura: ''tu padre ciertamente sabe.'' La reduplicación de la raíz para intensificación es un modismo semítico reflejado en la fraseología enfática de las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101022, 'spa', 'Nifal: ser conocido', 'Nifal pasivo: ''ser conocido,'' ''llegar a saberse,'' ''ser revelado.'' En Génesis 41:21 las vacas ''no se conocía'' que hubieran comido a las gordas. Éxodo 6:3 (''me di a conocer'') muestra el matiz reflexivo del Nifal. Las glosas pasivas en francés y alemán confirman la morfología.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101032, 'spa', 'conocer carnalmente', 'Intimidad sexual: ''conocer carnalmente.'' Génesis 4:1 (''Adán conoció a Eva su mujer'') inaugura este uso eufemístico. Los traductores a distintas lenguas navegan este sentido delicado: algunos conservan el eufemismo, otros optan por la claridad explícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101113, 'spa', 'ser dado a conocer', 'Sentido poco claro a partir de las glosas, aparece solo en Levítico 4:23, 28 con vocabulario cúltico especializado. Probablemente un sentido pasivo relacionado con el pecado que es revelado o puesto en conocimiento del oferente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101141, 'spa', 'Piel: hacer conocer', 'Piel intensivo-causativo: ''hacer conocer,'' aparece únicamente en las variantes textuales ketiv/qeré de Job 38:12. El Piel es más raro que el Hifil para esta función semántica, lo que sugiere una causación intensiva o especializada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101151, 'spa', 'Hitpael: darse a conocer', 'Hitpael reflexivo: ''darse a conocer,'' ''revelarse.'' En Génesis 45:1 José se da a conocer a sus hermanos. Números 12:6 describe cómo el SEÑOR se da a conocer en visiones: autorrevelación activa, no mera pasividad de ser conocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101170, 'spa', 'Pual: conocido, pariente', 'Participio pasivo intensivo Pual como sustantivo: ''conocido,'' ''pariente,'' ''allegado.'' En Rut 2:1 se presenta a Boaz como pariente de Noemí. El participio pasivo usado nominalmente indica a alguien que es conocido, es decir, un allegado o familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101184, 'spa', 'discernir, distinguir', 'Sentido poco claro, aparece una vez en 2 Samuel 19:35 donde el anciano Barzilai pregunta ''¿acaso puedo discernir?'' Probablemente se refiere a la capacidad de percepción sensorial o de distinguir entre lo bueno y lo malo en la vejez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101207, 'spa', 'hacer saber, instruir', 'Sentido poco claro, aparece una vez en 1 Samuel 21:3 donde David dice ''hice saber.'' Posiblemente un sentido causativo de informar o dar instrucciones, aunque el contexto resulta ambiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101208, 'spa', 'dar a conocer, declarar', 'dar a conocer, declarar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101209, 'spa', 'conocer, percibir', 'conocer, percibir');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101210, 'spa', 'ser conocido', 'ser conocido');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101237, 'spa', 'ensenar, instruir', 'ensenar, instruir');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101243, 'spa', 'Jedaías, nombre sacerdotal', 'Nombre personal teofórico que significa ''YHWH ha conocido/considerado'', portado por múltiples figuras sacerdotales. Principalmente el ancestro de una gran familia sacerdotal de la segunda división (1 Cr 24:7), cuyos 973 descendientes regresaron del exilio (Esd 2:36; Neh 7:39). Aparece también en listas de asentamiento postexílico (1 Cr 9:10; Neh 11:10), registros de turnos sacerdotales (Neh 12:6-7, 19, 21) y la corona simbólica de Zacarías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101246, 'spa', 'Adivino, espíritu familiar', 'Un espiritista, espíritu familiar o hechicero — persona (o el espíritu que canaliza) que dice poseer conocimiento oculto, especialmente mediante comunicación con los muertos. Casi siempre emparejado con אוֹב (médium/nigromante) como endíadis de adivinación prohibida. Condenado en Levítico 19:31; 20:6, 27 y Deuteronomio 18:11; expulsado por Saúl (1 S 28:3, 9) y Josías (2 R 23:24). Isaías contrasta la consulta a estos con buscar a YHWH.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101254, 'spa', 'Yah — la forma poética contraída del nombre divino Yahveh, empleada en la poesía', 'Yah — la forma poética contraída del nombre divino Yahveh, empleada en la poesía primitiva de victoria (Éx 15:2; 17:16), en citas proféticas (Is 12:2; 26:4; 38:11) y extensamente en el Salterio como núcleo de la doxología hallelu-Yah (Sal 113:1; 115:18; 146:1; 150:6). Su restricción a contextos litúrgicos, poéticos y exclamatorios la distingue del tetragrama completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101258, 'spa', 'atribuir, rendir gloria', 'atribuir, rendir gloria');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101259, 'spa', 'dar, entregar', 'dar, entregar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101260, 'spa', 'vamos! (exhortacion)', 'vamos! (exhortacion)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101266, 'spa', 'colocar, poner', 'colocar, poner');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101268, 'spa', 'Formas pasivas que significan «ser dado, ser concedido»', 'Formas pasivas que significan «ser dado, ser concedido»: 15 ocurrencias en Nifal/Hitpael, que abarcan decretos reales emitidos, fondos del templo asignados y provisiones suministradas del tesoro real. En Esdras 6:4 los gastos «serán dados» de la casa del rey; en Esdras 6:8-9 se especifican materiales que «han de ser dados» a los ancianos judíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101269, 'spa', 'Sentido activo Pe''al', 'Sentido activo Pe''al: dar, otorgar, conceder — 9 ocurrencias concentradas en las narrativas cortesanas de Daniel donde Dios es el sujeto. Dios «da» sabiduría y poder (Dn 2:21), «ha dado» a Nabucodonosor su reino (Dn 2:37-38), y Daniel reconoce «me has dado sabiduría» (Dn 2:23). El imperativo hab en Daniel 5:17 («da tus recompensas a otro») completa este grupo de agente activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101275, 'spa', 'Colocar, poner, asentar — una sola ocurrencia en Esdras 5', 'Colocar, poner, asentar — una sola ocurrencia en Esdras 5:16 donde Sesbasar «puso» los cimientos del templo de Jerusalén. Aquí יְהַב se extiende más allá de la transferencia de posesión hacia el posicionamiento espacial: algo es puesto en un lugar en vez de dado a una persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101277, 'spa', 'Entregar, rendir, ceder — 3 ocurrencias donde el dar implica ceder el control o ', 'Entregar, rendir, ceder — 3 ocurrencias donde el dar implica ceder el control o personas al poder de otro. Dios «entregó» los utensilios del templo en mano de Nabucodonosor (Esd 5:12), Sadrac y sus compañeros «entregaron» sus cuerpos al fuego (Dn 3:28), y en Daniel 7:25 los santos «serán entregados» en mano del cuerno pequeño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101290, 'spa', 'Jehú, rey de Israel — el nombre propio Jehú, compartido por varios individuos pe', 'Jehú, rey de Israel — el nombre propio Jehú, compartido por varios individuos pero dominado por el rey de Israel (r. ca. 841–814 a.C.). La gran mayoría de las 58 apariciones narran su violento golpe de estado y la purga del culto a Baal (2 Re 9–10). El profeta Jehú hijo de Hananí (1 Re 16:1, 7; 2 Cr 19:2; 20:34) y un guerrero davídico constituyen portadores secundarios del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101293, 'spa', 'Joacaz, rey — El nombre propio Joacaz (יְהוֹאָחָז) y su forma abreviada (יוֹאָחָ', 'Joacaz, rey — El nombre propio Joacaz (יְהוֹאָחָז) y su forma abreviada (יוֹאָחָז), que identifica a varias figuras biblicas, principalmente un rey de Israel (hijo de Jehu, 2 Re 13) y un rey de Juda (hijo de Josias, 2 Re 23:30-34). El elemento teoforico (''YHWH ha asido'') subraya la soberania divina sobre la sucesion real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101296, 'spa', 'Joas / Yehoash (nombre propio) — Nombre propio masculino teoforico (''YHWH es fue', 'Joas / Yehoash (nombre propio) — Nombre propio masculino teoforico (''YHWH es fuerte'' o ''YHWH ha otorgado'') llevado por multiples individuos, principalmente dos reyes de la monarquia dividida. Joas de Juda fue el rey nino escondido de Atalia e instalado por el sacerdote Joiada, quien reparo el templo pero fue luego asesinado (2 Re 11:2-12:21; 2 Cr 22:11-24:27). Joas de Israel, hijo de Joacaz, recibio la ultima profecia de Eliseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101297, 'spa', 'Yehud (Judá arameo)', 'Nombre propio arameo Yehud (יְהוּד), forma secundaria de Yehudá (Judá), empleado en las secciones arameas de Daniel y Esdras. Designa la provincia persa de Judá (Esd 5:1, 8; 7:14) y la comunidad judía en el exilio (''hijos del cautiverio de Yehud'', Dn 2:25; 5:13; 6:14). El español tradicionalmente lo traduce como ''Judá'', sin distinguir entre la forma hebrea y la aramea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101300, 'spa', 'Judíos, judeanos (arameo)', 'Sustantivo gentilicio arameo que significa ''judeano'' o ''judío'', referido a los miembros de la comunidad judía en la provincia persa de Yehud. Usado exclusivamente en la correspondencia aramea de Esdras (4:12, 23; 5:1, 5; 6:7-8, 14), funciona como identificador tanto étnico como administrativo en documentos oficiales persas. Los adversarios lo emplean al informar sobre la reconstrucción ante Artajerjes, y los decretos persas lo usan al autorizar la obra del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101303, 'spa', 'Judá (nombre propio)', 'El nombre propio Yehudá, aplicado al cuarto hijo de Jacob y Lea (Gn 29:35), a la tribu que llevó su nombre y recibió la bendición real (Gn 49:8-10), y al reino del sur con centro en Jerusalén. Las 819 ocurrencias, incluidas variantes con preposiciones y conjunciones, remiten a este único referente en sus dimensiones personal, tribal y geopolítica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101320, 'spa', 'Judío, persona judía — designa a una persona de identidad judía, usado tanto com', 'Judío, persona judía — designa a una persona de identidad judía, usado tanto como adjetivo gentilicio (ish yehudi, ''un hombre judío,'' Zac 8:23) como sustantivo en singular y plural. En Nehemías y Ester el término funciona como la etiqueta comunitaria estándar para el pueblo postexílico, con fuertes connotaciones de solidaridad pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101333, 'spa', 'Oficial de corte', 'Nombre propio del oficial de la corte de Joacim que recuperó y leyó públicamente el rollo profético de Jeremías. Las cuatro apariciones se concentran en Jer 36:14–23, donde Jehudí sirve de intermediario entre la palabra profética y el rey que la destruye columna por columna. Su nombre, etimológicamente vinculado a יְהוּדָה (Judá), confiere ironía a su papel en este episodio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101334, 'spa', 'Lengua judía', 'Usado adverbialmente para designar la lengua judía o judaica, el dialecto hebreo del reino del sur. Las seis apariciones son adverbiales: cuatro describen el discurso público del Rabsacés durante el asedio de Senaquerib (2 Kgs 18:26, 28 = Isa 36:11, 13), una describe la campaña psicológica asiria en 2 Chr 32:18, y otra lamenta la asimilación lingüística en Neh 13:24.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101337, 'spa', 'YHWH (el nombre divino)', 'El nombre personal divino Yahvé, revelado en la zarza ardiente (Éxodo 3:14-15) y usado en toda la Escritura como el nombre pactal que vincula a Dios con Israel. Las traducciones multilingües reflejan la antigua tradición de sustitución: el español Yahvé mantiene la forma fonética, el francés l''Éternel enfatiza la eternidad, y el alemán HERR sigue la tradición de Adonai. 6,522 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101351, 'spa', 'YHWH (nombre divino)', 'El nombre propio del Dios de Israel, el Tetragrama (יהוה), aqui en la vocalizacion variante usada en combinacion con Adonay para evitar la repeticion liturgica. La mayoria de estas 306 ocurrencias aparecen en la formula profetica «Adonay YHWH» (p. ej., Gn 15:2, 8; Dt 3:24; Ez passim). El nombre deriva de la raiz h-y-h (''ser'') y se consideraba demasiado sagrado para pronunciarlo, dando lugar a la practica del Qere.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101355, 'spa', 'Nombre propio teofórico', 'Nombre propio de varios personajes bíblicos que comparten el significado teofórico ''Yahvé ha otorgado''. El nombre aparece en dos variantes ortográficas: la forma completa יְהוֹזָבָד (Jehozabad) y la abreviada יוֹזָבָד (Jozabad). Entre los portadores notables se encuentran el asesino de Joás (2 Re 12:21), un comandante benjaminita bajo Josafat (2 Cr 17:18) y un portero levítico descendiente de Obed-edom (1 Cr 26:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101356, 'spa', 'Yehojanán (nombre propio)', 'Nombre personal teofórico que significa ''YHWH es clemente'', forma larga ancestral de ''Johanán'' y el griego ''Juan''. Portado por al menos ocho individuos distintos del período monárquico y postexílico: guerreros (1 Cr 12:5, 13), porteros levíticos (1 Cr 26:3), comandantes militares (2 Cr 17:15; 23:1), funcionarios (2 Cr 28:12), jefes sacerdotales (Neh 12:13, 42) y laicos en la reforma matrimonial de Esdras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101360, 'spa', 'Joiada, sacerdote — el nombre propio Yehoyada (Joiada), referido principalmente ', 'Joiada, sacerdote — el nombre propio Yehoyada (Joiada), referido principalmente a dos individuos: (a) el padre de Benaía, capitán de los cereteos y peleteos de David, recurrente en el patronímico formulaico ''Benaía hijo de Joiada'' (2 Sam 8:18; 23:20, 22; 1 Re 1:8, 26, 32, 36, 38, 44; 4:4); y (b) el sumo sacerdote que escondió al infante Joás durante seis años del reinado de Atalía y luego organizó el golpe que restauró la línea davídica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101364, 'spa', 'Yehoyakhín / Joaquín (nombre propio)', 'Nombre propio que significa ''YHWH establece'', portado por el hijo y sucesor de Joacim que reinó en Jerusalén tres meses a los dieciocho años antes de rendirse ante Nabucodonosor en 597 a.C. (2 R 24:6-12, 15). Su deportación junto con la reina madre, los cortesanos y ciudadanos prominentes marcó el primer gran exilio. 2 Reyes 25:27-30 registra su liberación del encarcelamiento babilónico tras 37 años.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101367, 'spa', 'Yehoyaqim (nombre propio)', 'Yehoyaqim (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101371, 'spa', 'Yehonadab / Jonadab (nombre propio)', 'Jonadab o Yehonadab (Yehonadav/Yonadav), nombre propio hebreo que significa ''YHWH es generoso/noble/dispuesto'', llevado por dos figuras bíblicas distintas. El primero es el hijo de Recab, ancestro zeloso de los recabitas cuyo estilo de vida austero —sin vino, sin casas, sin agricultura— se convirtió en lección profética de fidelidad (Jer 35:6-19; 2 R 10:15, 23). El segundo es el sobrino de David, hijo de Simea, descrito como hombre muy astuto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101375, 'spa', 'Jonatán (nombre propio) — nombre teofórico que significa ''YHWH ha dado,'' portado', 'Jonatán (nombre propio) — nombre teofórico que significa ''YHWH ha dado,'' portado principalmente por el hijo de Saúl, célebre por su vínculo pactual con David (1 Sam 18:1–3; 20:17) y su valentía en batalla (1 Sam 14:6–14). También designa a Jonatán hijo de Abiatar (2 Sam 15:27), al sobrino de David que mató a un gigante (2 Sam 21:21) y a varias figuras postexílicas en Esdras y Nehemías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101386, 'spa', 'Nombre de reina madre', 'Nombre de una reina madre preservado en registros reales oficiales. La complejidad textual (variantes Jehoadán/Yehoadín) y las diversas transliteraciones entre idiomas revelan una incertidumbre escribal persistente sobre su vocalización y morfología exactas. Como madre de un rey, habría ostentado un estatus político significativo en la corte de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101387, 'spa', 'Josadac (nombre propio)', 'Josadac (Yehōtsādāq), que significa ''YHWH es justo'', nombre propio del hijo del último sumo sacerdote preexílico Seraías y padre de Josué/Jesúa, el primer sumo sacerdote tras el exilio babilónico. Aparece en la genealogía de 1 Cr 6:14-15 como el sacerdote llevado al cautiverio, y se le identifica consistentemente como padre del sumo sacerdote Josué en los profetas postexílicos (Hag 1:1, 12; Zac 6:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101390, 'spa', 'Nombre propio hebreo masculino que significa «YHWH es exaltado», aplicado a vari', 'Nombre propio hebreo masculino que significa «YHWH es exaltado», aplicado a varios personajes. Los dos más prominentes son Joram de Judá (2 Re 8:16-24), cuyo desastroso reinado vio la revuelta edomita e incursiones filisteas, y Joram de Israel (2 Re 3:1; 9:14-24), rey de la dinastía omrida ejecutado por Jehú. Un sacerdote de este nombre participó en la delegación de enseñanza de la Torá de Josafat (2 Cr 17:8), y Toi de Hamat envió a su hijo Joram como emisario diplomático a David (2 Sam 8:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101397, 'spa', 'Josue (nombre propio)', 'Nombre propio hebreo que significa ''YHWH es salvacion'', llevado principalmente por Josue hijo de Nun, comandante militar y sucesor de Moises que dirigio la conquista de Canaan (Ex 17:9; Jos 1:1), y secundariamente por Josue el sumo sacerdote de la era de la restauracion (Hag 1:1; Zac 3:1). La forma contracta posterior Yeshua enlaza directamente con el griego Iesous (Jesus), confiriendo al nombre una profunda significacion tipologica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101403, 'spa', 'Josafat (nombre propio) — nombre teofórico que significa ''YHWH ha juzgado,'' port', 'Josafat (nombre propio) — nombre teofórico que significa ''YHWH ha juzgado,'' portado principalmente por el rey de Judá, hijo de Asa, quien reinó durante un período significativo de reforma y alianza (1 Re 15:24; 2 Cr 17–20). También designa a un cronista bajo David (2 Sam 8:16), al padre de Jehú (2 Re 9:2) y a un oficial salomónico (1 Re 4:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101410, 'spa', 'Gema preciosa', 'Piedra preciosa valorada por su excepcional dureza y belleza, empleada en contextos sagrados. La traducción generalizada como «diamante» en español, francés y alemán refleja una tradición interpretativa posterior, no una identificación segura. Su presencia en el pectoral y en la imagen profética del Edén subraya su categoría como una de las piedras más preciadas del mundo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101411, 'spa', 'Jahaz (topónimo)', 'El topónimo Jahaz (con variantes Yahats, Yahtsah, Jahasá) que designa una ciudad moabita de ubicación exacta incierta. Históricamente significativa como el sitio donde Israel derrotó a Sijón, rey de los amorreos, abriendo la Transjordania a la colonización (Nm 21:23; Dt 2:32; Jue 11:20). Fue asignada a Rubén (Jos 13:18) y designada ciudad levítica (1 Cr 6:63). Los oráculos proféticos contra Moab la invocan como símbolo del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101418, 'spa', 'Joab (nombre propio)', 'El nombre propio hebreo Yoav, compuesto teoforico que significa ''YHWH es padre''. Su referente principal es el sobrino de David por medio de Servia, quien sirvio como comandante en jefe de las fuerzas de Israel a lo largo de todo el reinado de David, desde la guerra civil con Is-boset (2 S 2:13) hasta la revuelta de Absalon (2 S 18:2) y su propia muerte bajo Salomon (1 R 2:34). Portadores menores incluyen un judita en 1 Cr 4:14 y una familia en Esd 2:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101424, 'spa', 'Joah (nombre propio)', 'Nombre propio teofórico que significa ''YHWH es hermano'', portado por cuatro individuos. El más prominente es el hijo de Asaf, cronista de Ezequías, que participó en las negociaciones durante la crisis asiria (2 Re 18:18, 26, 37; Is 36:3, 11, 22). También designa a un levita gersonita (1 Cr 6:21), un portero coraíta (1 Cr 26:4), un levita en la purificación del templo de Ezequías (2 Cr 29:12) y un levita supervisor en las reparaciones del templo bajo Josías (2 Cr 34:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101426, 'spa', 'Nombre real y administrativo', 'Nombre propio real y administrativo portado por varias figuras, todas compartiendo el significado teofórico ''Yahvé ha asido/agarrado.'' Las cuatro ocurrencias aquí emplean la forma abreviada יוֹאָחָז (Yoajaz). En español se distingue entre ''Joacaz'' y ''Yoajaz.'' BDB señala que el nombre es esencialmente intercambiable con Ocozías (אֲחַזְיָהוּ), los mismos elementos en orden inverso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101427, 'spa', 'Joel (nombre propio) — El nombre propio Yoel (Joel), compuesto teoforico de Yah ', 'Joel (nombre propio) — El nombre propio Yoel (Joel), compuesto teoforico de Yah + El que significa ''YHWH es Dios.'' Aplicado a al menos trece individuos distintos en la Biblia hebrea, incluyendo al primogenito de Samuel (1 Sam 8:2), un profeta (Joel 1:1), cantores levitas, jefes tribales y lideres postexilicos. La forma uniforme ''Joel'' en multiples idiomas atestigua su transliteracion estable a lo largo de la historia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101429, 'spa', 'Yoash / Joás (nombre propio) — Nombre teofórico que significa ''YHWH ha dado'' o ''', 'Yoash / Joás (nombre propio) — Nombre teofórico que significa ''YHWH ha dado'' o ''YHWH es fuerte'', aplicado a múltiples individuos bíblicos. Los portadores más destacados son Joás rey de Judá, ocultado de niño en el templo durante la usurpación de Atalía y coronado a los siete años (2 R 11:2-12; 2 Cr 24:1), y Joás rey de Israel, quien visitó al moribundo Eliseo y recibió el oráculo de victoria sobre Aram (2 R 13:14-25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101435, 'spa', 'Jobab (nombre propio)', 'Sustantivo propio masculino usado para cinco individuos distintos en la Biblia hebrea. El nombre probablemente deriva de una raíz que sugiere ''clamar'' o ''gritar'', también atestiguada en inscripciones sabeas (יהיבב). Su amplia distribución —abarcando linajes joctanitas, edomitas, cananeos y benjaminitas— muestra que era un nombre semítico común que trascendía fronteras étnicas. Pasajes clave incluyen Gn 10:29, Gn 36:33, Jos 11:1 y 1 Cr 8:9, 18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101437, 'spa', 'El año quincuagésimo en el calendario sagrado de Israel, proclamado con el toque', 'El año quincuagésimo en el calendario sagrado de Israel, proclamado con el toque de un cuerno de carnero en el Día de la Expiación. Durante este año, las tierras ancestrales vuelven a su clan original, las deudas son condonadas y los siervos hebreos quedan libres. Las traducciones multilingües emplean uniformemente préstamos léxicos del jubileo — «jubileo» (esp.), «jubilé» (fr.), «Jubeljahr» (al.) — reflejando el paso del término al vocabulario universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101438, 'spa', 'El cuerno de carnero como instrumento musical, usado como señal en contextos rit', 'El cuerno de carnero como instrumento musical, usado como señal en contextos rituales y militares. En Jericó, los sacerdotes portaban «shoferot ha-yovelim» (cuernos de carnero) delante del arca (Jos 6:4-13); en el Sinaí, un toque prolongado del יוֹבֵל señalaba la aproximación del pueblo (Ex 19:13). El español «cuerno/carnero» capta el sentido concreto derivado del animal, distinto del significado calendárico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101447, 'spa', 'Jozabad (nombre propio)', 'Nombre propio teofórico que significa ''YHWH ha otorgado'', compartido por múltiples individuos: guerreros gaditas que se unieron a David en Siclag (1 Cr 12:5, 21), levitas administradores de los depósitos y diezmos del templo bajo Ezequías (2 Cr 31:13) y Josías (2 Cr 35:9), un levita que ayudó a pesar los utensilios del templo devueltos (Esd 8:33) y hombres incluidos entre quienes tomaron esposas extranjeras (Esd 10:22-23). También aparece en Nehemías como levita supervisor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101451, 'spa', 'Nombre propio masculino Yojanán, que significa «YHWH ha sido misericordioso», ap', 'Nombre propio masculino Yojanán, que significa «YHWH ha sido misericordioso», aplicado a al menos ocho individuos distintos en la Biblia hebrea. Entre ellos se encuentran Johanán hijo de Carea, comandante judío tras la destrucción de Jerusalén (2 Re 25:23; Jer 40:8), un sumo sacerdote postexílico (Esd 10:6; Neh 12:22), un príncipe davídico (1 Cr 3:15), un portero levita del templo (1 Cr 26:3) y diversos líderes militares y civiles en Crónicas y Esdras-Nehemías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101453, 'spa', 'Nombre propio sacerdotal', 'Nombre propio que llevan figuras sacerdotales posexilicas en Nehemias. Joiada aparece como hijo de Eliasib en la sucesion sumo-sacerdotal (Neh 12:10-11) y como padre de uno que se caso con la hija de Sanbalat (Neh 13:28). El nombre tambien figura en listas genealogicas y de pacto (Neh 3:6; 12:22). Las traducciones transliteran uniformemente: ''Joiada'' (ingles/espanol), ''Jojada'' (frances/aleman).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101455, 'spa', 'Sumo sacerdote postexílico', 'Nombre propio de un sumo sacerdote postexílico, hijo de Jesúa, registrado en la genealogía sacerdotal de Neh 12. La forma abreviada יוֹיָקִים (Joiacim) se emplea en las cuatro ocurrencias, distinguiéndolo del rey Joaquim (יְהוֹיָקִים). Neh 12:10 traza la sucesión Jesúa, Joiacim y Eliasib.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101456, 'spa', 'Nombre propio sacerdotal', 'Nombre propio que designa figuras sacerdotales y laicas en el Judá postexílico. Como cabeza de la primera división sacerdotal (1 Cr 24:7; Neh 11:10), Jehoiarib desempeñó un papel litúrgico prominente. Un maestro con este nombre sirvió bajo Esdras (Esd 8:16). Un habitante judío de Jerusalén también llevó el nombre (Neh 11:5). La evidencia multilingüe muestra una transliteración uniforme: ''Joiarib/Yoyariv''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101460, 'spa', 'día, tiempo específico', 'Sentido temporal general: un día como unidad de tiempo, una fecha concreta o un período/era marcado por eventos. Este sentido masivamente dominante (2.231 ocurrencias) abarca ''el tercer día'' (Gn 2:2), ''en aquel día'' (Gn 26:32) y expresiones epocales como ''el día del SEÑOR.'' El prefijo preposicional כְּ (''en/el día de'') se adjunta con frecuencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101484, 'spa', 'días de vida, existencia', 'Sentido biográfico: ''sus días'' como metonimia del tiempo de vida, reinado o período asignado de una persona. Expresiones como ''los días de Péleg'' (Gn 10:25), ''todos los días de tu vida'' y ''sus días fueron 930 años'' emplean יוֹם en plural para abarcar toda una existencia. El sufijo posesivo es clave: ''sus días,'' ''tus días.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101494, 'spa', 'como los días de', 'Expresión comparativa-temporal ''como los días de,'' usando el prefijo כְּ para trazar una analogía entre la experiencia presente y un tiempo recordado o anticipado. Los siete años de Jacob parecieron ''como unos pocos días'' por su amor a Raquel (Gn 29:20); ''como tus días, así será tu fuerza'' (Dt 33:25). La estructura de símil es inconfundible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101503, 'spa', 'dos días', 'La forma dual יוֹמָיִם que indica exactamente dos días: una distinción gramatical que el hebreo marca morfológicamente. Aparece en regulaciones sobre un siervo que sobrevive ''un día o dos'' (Éx 21:21), el pueblo recogiendo maná por ''dos días'' (Nm 11:19), y la nube demorándose ''dos días'' (Nm 9:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101506, 'spa', 'luz del día, jornada', 'Sentido de luz diurna: la porción luminosa del ciclo de 24 horas en contraste con la noche. Jacob declara: ''de día me consumía el calor y de noche la helada'' (Gn 31:39). Esto contrasta con el sentido 1, donde ''día'' es una unidad calendárica; aquí es la mitad luminosa del ciclo diario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101520, 'spa', 'dia, dias (arameo) — Unidad de tiempo que abarca dias individuales, fechas del c', 'dia, dias (arameo) — Unidad de tiempo que abarca dias individuales, fechas del calendario, duraciones y eras historicas en arameo biblico. Se usa para fechas especificas como el tercero de Adar (Esd 6:15), para modismos de provision diaria (Esd 6:9) y para periodos extensos como reinados reales (Dan 2:44; 5:11). El epiteto teologicamente significativo ''Anciano de Dias'' (Dan 7:9, 13, 22) usa el plural para evocar la soberania de Dios a traves de todas las edades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101528, 'spa', 'De día, durante el día — adverbio temporal que significa ''de día'' o ''durante las', 'De día, durante el día — adverbio temporal que significa ''de día'' o ''durante las horas diurnas,'' utilizado para situar eventos en las horas de luz y frecuentemente emparejado con laylah (''de noche'') para expresar duración incesante o protección divina continua. El uso paradigmático es la imagen de la columna del Éxodo: ''El SEÑOR iba delante de ellos de día en una columna de nube'' (Éx 13:21), motivo recordado a lo largo de los Salmos y los Profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101532, 'spa', 'Grecia (entidad geográfico-política)', 'Grecia como entidad geográfica y política, usada especialmente en textos apocalípticos y proféticos tardíos. Daniel 8:21 identifica al ''rey de Javán'' como el gobernante de Grecia (la LXX lee Ἑλλάς), y Daniel 10:20 y 11:2 describen al ''príncipe de Javán'' como potencia histórica mundial. Zacarías 9:13 enfrenta a los hijos de Sión contra los hijos de Javán, marcando la transición del nombre propio al topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101533, 'spa', 'Javán (persona, ancestro epónimo)', 'El nombre personal Javán (יָוָן), hijo de Jafet, listado en la Tabla de las Naciones (Gn 10:2; 1 Cr 1:5) y ancestro epónimo de los griegos jonios. Sus ''hijos'' — Elisá, Tarsis, Quitim y Dodanim (Gn 10:4; 1 Cr 1:7) — representan pueblos de las costas del Egeo y el Mediterráneo occidental. En Isaías 66:19 y Ezequiel 27:13, Javán aparece junto a Tubal y Mesec como pueblos comerciantes lejanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101537, 'spa', 'Jonadab (nombre propio)', 'Nombre propio masculino Yonadab/Yehonadab (יוֹנָדָב / יְהוֹנָדָב), que significa ''YHWH es noble'' o ''YHWH ha impulsado''. Se refiere a dos individuos: (a) Jonadab hijo de Simea, sobrino de David y astuto consejero en el episodio de Amnón y Tamar (2 S 13:3, 5, 32, 35); (b) Jonadab/Yehonadab hijo de Recab, patriarca de los recabitas que se alió con Jehú contra el culto a Baal (2 R 10:15, 23) y cuyo voto ascético Jeremías elogia como modelo de fidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101540, 'spa', 'paloma (ave literal) — El ave literal (Columba livia o especies afines), que apa', 'paloma (ave literal) — El ave literal (Columba livia o especies afines), que aparece como mensajera de Noé regresando con la rama de olivo (Gn 8:8-12), como ofrenda sacrificial junto con tórtolas en Levítico (Lv 1:14; 12:6), y en símiles proféticos que describen gemidos, vuelo o ingenuidad, como la ''paloma incauta'' de Oseas (7:11).');